<script setup lang="ts">import {computed,ref} from 'vue';import type {Run,Finding,User} from '../types/domain';import {researchApi} from '../api/research';import {useAsync} from '../hooks/useAsync';import PageTitle from '../components/common/PageTitle.vue';import Badge from '../components/common/Badge.vue';import Table from '../components/common/Table.vue';import Empty from '../components/common/Empty.vue';import Notice from '../components/common/Notice.vue';import HistogramBins from '../components/HistogramBins.vue';import FindingSummary from '../components/FindingSummary.vue';import {dec,scientific,labelBin} from '../utils/format';const props=defineProps<{runs:Run[];findings:Finding[];selectedId:number;features:Record<string,string>;user:User;reload:()=>Promise<any>}>();const emit=defineEmits<{select:[run:Run]}>();const run=computed(()=>props.runs.find(r=>r.id===props.selectedId)||props.runs[0]),items=computed(()=>props.findings.filter(f=>f.run_id===run.value?.id)),focusId=ref(0),focus=computed(()=>items.value.find(f=>f.id===focusId.value)||items.value[0]),name=ref('十一月来源结构补采计划'),slice=ref('studio设备 / 长时片段覆盖'),target=ref(200),rationale=ref('先核对采集来源与缺失原因，再补充覆盖不足切片；漂移不等同模型劣化。');const {task,act}=useAsync();async function submit(){await act(async()=>{await researchApi.plan({run_id:run.value!.id,name:name.value,finding_ids:[focus.value!.id],target_slice:slice.value,sample_target:target.value,rationale:rationale.value});await props.reload()},'补采计划已建立，等待负责人审稿')};</script><template><template v-if="run"><PageTitle index="04 / DISTRIBUTION FINDINGS" title="把变化，读到具体的桶里。" description="原p、校正q与分布差异并排呈现。建议核对标记使用FDR或PSI≥.2/JS≥.05启发阈值，二者含义不同。"/><Notice :error="task.error||run.error" :message="task.message"/><div class="run-selector"><select aria-label="选择校样" :value="run.id" @change="emit('select',runs.find(r=>r.id===Number(($event.target as HTMLSelectElement).value))!)"><option v-for="r in runs" :key="r.id" :value="r.id">{{r.name}}</option></select><Badge :status="run.status"/><small>SHA-256 {{run.result.fingerprint?.slice(0,28)||'等待计算'}}…</small></div><template v-if="items.length"><div class="family-strip"><span>参考 {{run.result.reference_n}} / 候选 {{run.result.candidate_n}}</span><span>冻结箱来自参考 · 平滑α={{run.config.smoothing}}</span><span>BH检验族 m={{run.result.test_family?.m}} · FDRα={{run.config.fdr_alpha}}</span></div><Table :headers="['特征 / 核对标记','PSI ln','JS log₂','KS统计量','原 p','BH q / FDR','']"><tr v-for="f in items" :key="f.id" :class="{selected:f.id===focus?.id}"><td><strong>{{features[f.feature]}}</strong><Badge :status="f.status"/></td><td>{{dec(f.metrics.psi)}}</td><td>{{dec(f.metrics.js)}}</td><td>{{dec(f.metrics.ks_statistic)}}</td><td>{{scientific(f.metrics.p_value)}}</td><td>{{scientific(f.metrics.q_value)}}<small>{{f.metrics.q_value==null?'类别不做KS':f.metrics.fdr_reject?'q≤α，拒绝':'q>α，未拒绝'}}</small></td><td><button class="text-button" @click="focusId=f.id">校对分箱 ↗</button></td></tr></Table><section v-if="focus" class="finding-detail"><div class="section-title"><h2>{{features[focus.feature]}} / 冻结分箱</h2><small>仅参考拟合 · {{focus.metrics.binning.kind}}</small></div><FindingSummary :finding="focus"/><HistogramBins :finding="focus"/><div class="missing-note">参考缺失 {{focus.metrics.reference_missing}} / 候选缺失 {{focus.metrics.candidate_missing}}；缺失进入独立桶。<span v-if="focus.metrics.p_value!=null">KS非缺失样本 {{focus.metrics.ks_reference_n}} / {{focus.metrics.ks_candidate_n}}。</span><span v-else>候选新类别进入__NEW__，参考类别集合保持冻结。</span></div><Table :headers="['冻结箱','参考计数','候选计数']"><tr v-for="(label,i) in focus.metrics.binning.labels" :key="i"><td class="mono">{{labelBin(label)}}</td><td>{{focus.metrics.reference_counts[i]}}</td><td>{{focus.metrics.candidate_counts[i]}}</td></tr></Table></section><form v-if="user.role!=='viewer'&&focus" class="editor plan-editor" @submit.prevent="submit"><small>NEXT / 从差异到采集说明</small><h2>以当前发现建立补采草案</h2><div class="form-grid"><label>计划名称<input v-model="name" required maxlength="100"/></label><label>目标切片<input v-model="slice" required maxlength="160"/></label><label>目标片段数<input type="number" v-model.number="target" min="20" max="10000" step="1" required/></label></div><label>补采依据<textarea rows="3" v-model="rationale" required maxlength="500"/></label><button class="primary" :disabled="task.busy">建立补采计划 →</button></form></template><Empty v-else title="比较尚未完成或失败" help="等待worker；若切片为空或参考常量，调整输入后重新建立比较。"/></template><Empty v-else title="尚无校样" help="先从比较配置提交参考与候选快照。"/></template>
